# sliding-window-maximum
# Edit the demonstration input below, then Run.
import json

from collections import Counter, deque

def window_max(a, k):
    if not 0 < k <= len(a):
        return []
    queue, result = deque(), []
    for i, value in enumerate(a):
        while queue and queue[0] <= i - k:
            queue.popleft()
        while queue and a[queue[-1]] <= value:
            queue.pop()
        queue.append(i)
        if i >= k - 1:
            result.append(a[queue[0]])
    return result

# Demonstration input
result = window_max([1,3,-1,-3,5,3,6,7], 3)
print(json.dumps(result, sort_keys=True))

