from collections import deque

def tsp(cost):
    n = len(cost)
    dp = [[float('inf')] * n for _ in range(1 << n)]
    dp[1][0] = 0
    for mask in range(1 << n):
        for node in range(n):
            if mask & (1 << node):
                for child in range(n):
                    if not mask & (1 << child):
                        next_mask = mask | (1 << child)
                        dp[next_mask][child] = min(dp[next_mask][child], dp[mask][node] + cost[node][child])
