# bor-vka-s-minimum-spanning-tree
# Edit the demonstration input below, then Run.
import json

from collections import deque

import heapq

class Components:
    def __init__(self, n):
        self.parent = list(range(n))
        self.size = [1] * n
    def find(self, node):
        while node != self.parent[node]:
            self.parent[node] = self.parent[self.parent[node]]
            node = self.parent[node]
        return node
    def union(self, a, b):
        a, b = self.find(a), self.find(b)
        if a == b:
            return False
        if self.size[a] < self.size[b]:
            a, b = b, a
        self.parent[b] = a
        self.size[a] += self.size[b]
        return True

def boruvka(n, edges):
    components, total = Components(n), 0
    while True:
        cheapest = {}
        for a, b, weight in edges:
            first, second = components.find(a), components.find(b)
            if first == second:
                continue
            for root in (first, second):
                if root not in cheapest or weight < cheapest[root][2]:
                    cheapest[root] = (a, b, weight)
        changed = False
        for a, b, weight in cheapest.values():
            if components.union(a, b):
                total += weight
                changed = True
        if not changed:
            return total

