import json

import math

def hamiltonian(graph):
    path, used = [], set()
    def visit(node):
        path.append(node)
        used.add(node)
        if len(path) == len(graph):
            return list(path)
        for child in graph[node]:
            if child not in used:
                answer = visit(child)
                if answer is not None:
                    return answer
        used.remove(node)
        path.pop()
        return None
    for start in range(len(graph)):
        answer = visit(start)
        if answer is not None:
            return answer
    return None

