import json

import heapq

import math

def insertion(a):
    a = list(a)
    for i in range(1, len(a)):
        value, j = a[i], i - 1
        while j >= 0 and a[j] > value:
            a[j + 1] = a[j]
            j -= 1
        a[j + 1] = value
    return a

def merge(a, b):
    i, j, result = 0, 0, []
    while i < len(a) and j < len(b):
        if a[i] <= b[j]:
            result.append(a[i])
            i += 1
        else:
            result.append(b[j])
            j += 1
    return result + a[i:] + b[j:]

def timsort(a):
    """Educational natural-run Timsort: minrun extension and run-stack invariants.
    Merges use a linear merge rather than production galloping optimizations.
    """
    n = len(a)
    runs, i = [], 0
    minrun = n
    remainder = 0
    while minrun >= 64:
        remainder |= minrun & 1
        minrun >>= 1
    minrun += remainder
    def join(index):
        runs[index:index + 2] = [merge(runs[index], runs[index + 1])]
    while i < n:
        end = i + 1
        if end < n and a[end] < a[i]:
            while end < n and a[end] < a[end - 1]:
                end += 1
            run = list(reversed(a[i:end]))
        else:
            while end < n and a[end] >= a[end - 1]:
                end += 1
            run = list(a[i:end])
        extended = min(n, max(end, i + minrun))
        run = insertion(run + list(a[end:extended]))
        i = extended
        runs.append(run)
        while len(runs) >= 2:
            k = len(runs) - 2
            if (k > 0 and len(runs[k - 1]) <= len(runs[k]) + len(runs[k + 1])) or (k > 1 and len(runs[k - 2]) <= len(runs[k - 1]) + len(runs[k])):
                if len(runs[k - 1]) < len(runs[k + 1]):
                    k -= 1
            elif len(runs[k]) > len(runs[k + 1]):
                break
            join(k)
    while len(runs) > 1:
        join(len(runs) - 2)
    return runs[0] if runs else []

# Demonstration input
result = timsort([8,7,6,1,2,5,4,3])
print(json.dumps(result, sort_keys=True))

