import json

import heapq

import math

def merge(a, b):
    i, j, result = 0, 0, []
    while i < len(a) and j < len(b):
        if a[i] <= b[j]:
            result.append(a[i])
            i += 1
        else:
            result.append(b[j])
            j += 1
    return result + a[i:] + b[j:]

def merge_sort(a):
    if len(a) < 2:
        return list(a)
    mid = len(a) // 2
    return merge(merge_sort(a[:mid]), merge_sort(a[mid:]))

def k_merge(lists):
    heap = [(a[0], i, 0) for i, a in enumerate(lists) if a]
    heapq.heapify(heap)
    result = []
    while heap:
        value, i, j = heapq.heappop(heap)
        result.append(value)
        if j + 1 < len(lists[i]):
            heapq.heappush(heap, (lists[i][j + 1], i, j + 1))
    return result

def external_merge(a, chunk_size):
    """In-memory simulation of external runs; no filesystem access in the worker."""
    runs = [merge_sort(a[i:i + chunk_size]) for i in range(0, len(a), chunk_size)]
    return k_merge(runs)

