import json

import heapq

import math

def insertion(a):
    a = list(a)
    for i in range(1, len(a)):
        value, j = a[i], i - 1
        while j >= 0 and a[j] > value:
            a[j + 1] = a[j]
            j -= 1
        a[j + 1] = value
    return a

def median_of_medians(a, k):
    if len(a) <= 5:
        return insertion(a)[k]
    medians = [insertion(a[i:i + 5])[len(a[i:i + 5]) // 2] for i in range(0, len(a), 5)]
