# infix-to-postfix
# Edit the demonstration input below, then Run.
import json

from collections import deque

def shunting_yard(tokens):
    """Tokenized operands/operators; ^ is right associative. No unary operators."""
    precedence = {'+': 1, '-': 1, '*': 2, '/': 2, '^': 3}
    stack, result = [], []
    for token in tokens:
        if token == '(':
            stack.append(token)
        elif token == ')':
            while stack and stack[-1] != '(':
                result.append(stack.pop())
            if not stack:
                raise ValueError('Unbalanced parentheses')
            stack.pop()
        elif token in precedence:
            while stack and stack[-1] in precedence and (precedence[stack[-1]] > precedence[token] or (precedence[stack[-1]] == precedence[token] and token != '^')):
                result.append(stack.pop())
            stack.append(token)
        else:
            result.append(token)
    if '(' in stack:
        raise ValueError('Unbalanced parentheses')
    return result + list(reversed(stack))

# Demonstration input
result = shunting_yard(['2','+','3','*','4'])
print(json.dumps(result, sort_keys=True))

