# postfix-evaluation
# Edit the demonstration input below, then Run.
import json

from collections import deque

def postfix(tokens):
    stack = []
    for token in tokens:
        if token not in ('+', '-', '*', '/'):
            stack.append(int(token))
            continue
        right, left = stack.pop(), stack.pop()
        if token == '+':
            stack.append(left + right)
        elif token == '-':
            stack.append(left - right)
        elif token == '*':
            stack.append(left * right)
        else:
            stack.append(int(left / right))
    return stack[-1]

# Demonstration input
result = postfix(['2','3','+','4','*'])
print(json.dumps(result, sort_keys=True))

