    pivot = node.left
    node.left = pivot.right
    pivot.right = node
    update_height(node)
    update_height(pivot)
    return pivot

def rotate_left(node):
    pivot = node.right
    node.right = pivot.left
    pivot.left = node
    update_height(node)
    update_height(pivot)
    return pivot

