import json

from collections import deque

def binary_trie_xor(values, query, width=8):
    """Nonnegative values fitting width bits."""
    root = {}
    for value in values:
        node = root
        for bit in range(width - 1, -1, -1):
            node = node.setdefault((value >> bit) & 1, {})
    node, answer = root, 0
    for bit in range(width - 1, -1, -1):
        desired = 1 - ((query >> bit) & 1)
        if desired in node:
            answer |= 1 << bit
            node = node[desired]
        else:
            node = node[1 - desired]
    return answer

